def transform_demo1():
    """Demo 1: 2s at (3,8), (6,4), (6,12), (9,10), (11,7)"""
    output = [[0]*12 for _ in range(19)]
    twos = [(3,8), (6,4), (6,12), (9,10), (11,7)]

    # For each row with multiple 2s, fill between them
    twos_by_row = {}
    for r, c in twos:
        if r not in twos_by_row:
            twos_by_row[r] = []
        twos_by_row[r].append(c)

    for r, cols in twos_by_row.items():
        for i in range(len(cols)-1):
            for c in range(cols[i]+1, cols[i+1]):
                output[r][c] = 3

    # For each col with multiple 2s, fill between them  
    twos_by_col = {}
    for r, c in twos:
        if c not in twos_by_col:
            twos_by_col[c] = []
        twos_by_col[c].append(r)

    for c, rows in twos_by_col.items():
        for i in range(len(rows)-1):
            for r in range(rows[i]+1, rows[i+1]):
                output[r][c] = 3

    # Get 3s
    return set((r,c) for r in range(19) for c in range(12) if output[r][c] == 3)

