def transform(grid):
    """
    For each pair of 2s that are adjacent (no other 2 between them) 
    on the same row or column, fill the segment between them with 3s.
    """
    output = [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find all 2s
    twos = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]

    # For each row with multiple 2s, fill between adjacent pairs
    twos_by_row = {}
    for r, c in twos:
        if r not in twos_by_row:
            twos_by_row[r] = []
        twos_by_row[r].append(c)

    for r, col_list in twos_by_row.items():
        col_list = sorted(col_list)
        for i in range(len(col_list) - 1):
            for c in range(col_list[i] + 1, col_list[i + 1]):
                output[r][c] = 3

    # For each col with multiple 2s, fill between adjacent pairs
    twos_by_col = {}
    for r, c in twos:
        if c not in twos_by_col:
            twos_by_col[c] = []
        twos_by_col[c].append(r)

    for c, row_list in twos_by_col.items():
        row_list = sorted(row_list)
        for i in range(len(row_list) - 1):
            for r in range(row_list[i] + 1, row_list[i + 1]):
                output[r][c] = 3

    return output

